export async function main(ns) {
  ns.tprint(`Hostname: ${ns.getHostname()}`);
  ns.tprint("Network Scan:");

  const scanned = new Set();
  const queue = ["home"];
  scanned.add("home");

  while (queue.length > 0) {
    const current = queue.shift();
