/** @param {NS} ns */
export async function main(ns) {
  const candidates = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', 'nectar-net', 'CSEC'];
  let best = null;
  let bestMaxMoney = 0;

  for (const srv of candidates) {
    if (!ns.hasRootAccess(srv)) continue;
    const maxMoney = ns.getServerMaxMoney(srv);
    if (maxMoney > bestMaxMoney) {
      bestMaxMoney = maxMoney;
      best = srv;
    }
  }

  if (!best) {
    ns.tprint('ERROR: no rooted targets found');
    return;
  }

  ns.tprint(`Targeting: ${best}`);
  let actionCount = 0;

  while (true) {
    const sec = ns.getServerSecurityLevel(best);
    const money = ns.getServerMoneyAvailable(best);
    const maxMoney = ns.getServerMaxMoney(best);
    const minSec = 1; // baseline minimum security

    if (sec > minSec + 5) {
      await ns.weaken(best);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }

    actionCount++;
    if (actionCount % 20 === 0) {
      ns.tprint(`[${actionCount}] sec=${sec.toFixed(1)} money=${(money / 1e9).toFixed(2)}B/${(maxMoney / 1e9).toFixed(2)}B`);
    }

    await ns.sleep(100);
  }
}

